import { useState, useEffect, useRef } from 'react';
import axios from '../axiosConfig';

// ============================================================
//  ابزارهای کمکی
// ============================================================
const fmt = (n) => Math.round(n || 0).toLocaleString('fa-IR');

const formatDate = (iso) => {
  if (!iso) return '—';
  const d = new Date(iso);
  if (isNaN(d.getTime())) return '—';
  return d.toLocaleTimeString('fa-IR', { hour: '2-digit', minute: '2-digit' });
};

const formatDay = (iso) => {
  if (!iso) return '';
  const d = new Date(iso);
  if (isNaN(d.getTime())) return '';
  const days = ['یکشنبه', 'دوشنبه', 'سه‌شنبه', 'چهارشنبه', 'پنجشنبه', 'جمعه', 'شنبه'];
  return days[d.getDay()];
};

const formatShortDate = (iso) => {
  if (!iso) return '';
  const d = new Date(iso);
  if (isNaN(d.getTime())) return '';
  return d.toLocaleDateString('fa-IR', { month: 'short', day: 'numeric' });
};

// ============================================================
//  StatCard — مطابق طراحی داشبورد
// ============================================================
function VisitorStatCard({ icon, label, value, sub, variant }) {
  const styles = {
    online: {
      bg: 'bg-accent-50 dark:bg-accent-500/15 border-accent-200 dark:border-accent-500/30',
      value: 'text-accent-700 dark:text-accent-300',
      sub: 'text-accent-600 dark:text-accent-400',
      dot: 'bg-accent-500 animate-pulse',
    },
    today: {
      bg: 'bg-brand-50 dark:bg-brand-500/15 border-brand-200 dark:border-brand-500/30',
      value: 'text-brand-700 dark:text-brand-300',
      sub: 'text-brand-600 dark:text-brand-400',
      dot: '',
    },
    week: {
      bg: 'bg-paper-50 dark:bg-ink-800 border-ink-200 dark:border-dark-700',
      value: 'text-ink-800 dark:text-cream-100',
      sub: 'text-ink-400 dark:text-cream-500',
      dot: '',
    },
    month: {
      bg: 'bg-ink-900 dark:bg-ink-950 border-ink-700 text-cream-100',
      value: 'text-cream-50',
      sub: 'text-cream-400',
      dot: '',
    },
  };
  const s = styles[variant] || styles.week;

  return (
    <div className={`${s.bg} border rounded-3xl p-3 sm:p-4 shadow-soft hover:shadow-lifted transition-all relative overflow-hidden`}>
      {variant === 'online' && (
        <div className="absolute top-2 right-2 flex items-center gap-1">
          <span className={`w-2 h-2 rounded-full ${s.dot}`} aria-hidden="true" />
        </div>
      )}
      <div className="flex items-center justify-between mb-2">
        <span className="text-lg sm:text-xl" aria-hidden="true">{icon}</span>
        <span className="text-[10px] sm:text-[11px] font-black text-right leading-tight opacity-80">
          {label}
        </span>
      </div>
      <div className={`text-xl sm:text-2xl font-display font-black tracking-tight font-num tabular-nums ${s.value}`}>
        {value}
      </div>
      {sub && (
        <div className={`text-[10px] mt-1 ${s.sub} truncate font-bold`}>{sub}</div>
      )}
    </div>
  );
}

// ============================================================
//  نمودار میله‌ای ساده
// ============================================================
function VisitorChart({ data }) {
  if (!data || data.length === 0) {
    return (
      <div className="text-center text-sm text-ink-400 dark:text-cream-500 py-8">
        <div className="text-4xl mb-2 opacity-50">📊</div>
        <div className="text-xs font-bold">داده‌ای برای نمایش نیست</div>
      </div>
    );
  }

  const maxVal = Math.max(...data.map((d) => d.total), 1);

  return (
    <div className="space-y-2">
      {/* نمودار */}
      <div className="flex items-end gap-1.5 sm:gap-2 h-32 sm:h-40">
        {data.map((day, i) => {
          const totalH = (day.total / maxVal) * 100;
          const usersH = day.total > 0 ? (day.users / day.total) * totalH : 0;
          const guestsH = day.total > 0 ? (day.guests / day.total) * totalH : 0;

          return (
            <div key={i} className="flex-1 flex flex-col items-center justify-end h-full group relative">
              {/* tooltip */}
              <div className="absolute -top-8 opacity-0 group-hover:opacity-100 transition pointer-events-none bg-ink-900 text-cream-50 text-[10px] px-2 py-1 rounded-lg whitespace-nowrap z-10 font-num">
                {fmt(day.total)} بازدید
              </div>

              {/* ستون‌ها */}
              <div className="w-full flex flex-col-reverse rounded-t-lg overflow-hidden" style={{ height: `${totalH}%`, minHeight: day.total > 0 ? '4px' : '0' }}>
                <div
                  className="bg-brand-500 transition-all duration-500"
                  style={{ height: `${usersH}%` }}
                  title={`کاربر: ${fmt(day.users)}`}
                />
                <div
                  className="bg-ink-300 dark:bg-ink-600 transition-all duration-500"
                  style={{ height: `${guestsH}%` }}
                  title={`مهمان: ${fmt(day.guests)}`}
                />
              </div>

              {/* روز هفته */}
              <span className="text-[9px] sm:text-[10px] text-ink-500 dark:text-cream-400 mt-1.5 font-bold truncate w-full text-center">
                {formatDay(day.date)}
              </span>
              <span className="text-[8px] text-ink-400 dark:text-cream-500 font-num">
                {formatShortDate(day.date)}
              </span>
            </div>
          );
        })}
      </div>

      {/* راهنما */}
      <div className="flex gap-4 justify-center text-[10px] font-bold">
        <div className="flex items-center gap-1.5">
          <div className="w-2.5 h-2.5 bg-brand-500 rounded"></div>
          <span className="text-ink-600 dark:text-cream-300">کاربران لاگین‌کرده</span>
        </div>
        <div className="flex items-center gap-1.5">
          <div className="w-2.5 h-2.5 bg-ink-300 dark:bg-ink-600 rounded"></div>
          <span className="text-ink-600 dark:text-cream-300">مهمان‌ها</span>
        </div>
      </div>
    </div>
  );
}

// ============================================================
//  کامپوننت اصلی
// ============================================================
export default function VisitorStats() {
  const [stats, setStats] = useState(null);
  const [loading, setLoading] = useState(true);
  const heartbeatRef = useRef(null);

  const fetchStats = () => {
    axios
      .get('/admin/dashboard/visitors')
      .then((res) => {
        setStats(res.data);
        setLoading(false);
      })
      .catch(() => {
        setLoading(false);
      });
  };

  useEffect(() => {
    fetchStats();
    // آپدیت هر ۳۰ ثانیه
    const interval = setInterval(fetchStats, 30000);

    // heartbeat — هر ۶۰ ثانیه
    const sendHeartbeat = () => {
      axios.get('/api/heartbeat').catch(() => {});
    };
    sendHeartbeat(); // یکی هم اول
    heartbeatRef.current = setInterval(sendHeartbeat, 60000);

    return () => {
      clearInterval(interval);
      if (heartbeatRef.current) clearInterval(heartbeatRef.current);
    };
  }, []);

  if (loading) {
    return (
      <div className="bg-paper-50 dark:bg-ink-800 border border-ink-200 dark:border-dark-700 rounded-3xl shadow-soft p-4 sm:p-5">
        <div className="animate-pulse">
          <div className="h-5 w-32 bg-paper-200 dark:bg-ink-700 rounded mb-4"></div>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
            {[1, 2, 3, 4].map((i) => (
              <div key={i} className="h-20 bg-paper-200 dark:bg-ink-700 rounded-2xl"></div>
            ))}
          </div>
        </div>
      </div>
    );
  }

  if (!stats) {
    return null; // اگر خطا بود، چیزی نمایش نده
  }

  // اگر جدول وجود نداشت
  if (stats.table_exists === false) {
    return (
      <div className="bg-rose-50 dark:bg-rose-500/10 border border-rose-200 dark:border-rose-500/30 rounded-3xl p-4 text-center">
        <div className="text-2xl mb-2">⚠️</div>
        <p className="text-sm font-bold text-rose-700 dark:text-rose-300">
          جدول آمار بازدید ساخته نشده است
        </p>
        <p className="text-xs text-rose-600 dark:text-rose-400 mt-1">
          دستور python install_visitor_stats.py را اجرا کنید
        </p>
      </div>
    );
  }

  return (
    <div className="space-y-3 sm:space-y-4">
      {/* ===== هدر آمار بازدید ===== */}
      <div className="bg-ink-900 dark:bg-ink-950 text-cream-100 rounded-3xl shadow-soft relative overflow-hidden">
        <div className="absolute -top-12 -left-12 w-40 h-40 bg-accent-500/10 rounded-full" aria-hidden="true" />
        <div className="absolute -bottom-16 -right-16 w-56 h-56 bg-brand-500/5 rounded-full" aria-hidden="true" />

        <div className="relative p-4 sm:p-5">
          <div className="flex items-center justify-between mb-4">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 sm:w-11 sm:h-11 rounded-2xl bg-brand-gradient flex items-center justify-center text-xl sm:text-2xl flex-shrink-0 shadow-brand" aria-hidden="true">
                📊
              </div>
              <div>
                <h2 className="font-display font-black text-base sm:text-lg tracking-tight">
                  آمار بازدیدکنندگان
                </h2>
                <p className="text-[10px] sm:text-[11px] text-cream-300/80 mt-0.5 flex items-center gap-1.5">
                  <span className="w-1.5 h-1.5 rounded-full bg-accent-400 animate-pulse" aria-hidden="true" />
                  <span>آمار زنده‌ی بازدید سایت</span>
                </p>
              </div>
            </div>
          </div>

          {/* ۴ کارت آمار */}
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-2 sm:gap-3">
            <VisitorStatCard
              icon="🟢"
              label="آنلاین هم‌اکنون"
              value={fmt(stats.online_now.total)}
              sub={`${fmt(stats.online_now.users)} کاربر · ${fmt(stats.online_now.guests)} مهمان`}
              variant="online"
            />
            <VisitorStatCard
              icon="📅"
              label="بازدید امروز"
              value={fmt(stats.today.total)}
              sub={`${fmt(stats.today.users)} کاربر · ${fmt(stats.today.guests)} مهمان`}
              variant="today"
            />
            <VisitorStatCard
              icon="📆"
              label="این هفته"
              value={fmt(stats.week.total)}
              sub="بازدید کل"
              variant="week"
            />
            <VisitorStatCard
              icon="🗓️"
              label="این ماه"
              value={fmt(stats.month.total)}
              sub={`کل: ${fmt(stats.all_time.total)}`}
              variant="month"
            />
          </div>
        </div>
      </div>

      {/* ===== نمودار + تفکیک دستگاه ===== */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-3 sm:gap-4">
        {/* نمودار ۷ روز */}
        <div className="lg:col-span-2 bg-paper-50 dark:bg-ink-800 border border-ink-200 dark:border-dark-700 rounded-3xl shadow-soft overflow-hidden">
          <div className="px-4 sm:px-5 py-3 sm:py-4 border-b border-ink-200 dark:border-dark-700 flex items-center gap-3 bg-paper-100/50 dark:bg-ink-900/30">
            <div className="w-9 h-9 rounded-2xl bg-brand-100 dark:bg-brand-500/20 flex items-center justify-center text-lg flex-shrink-0 text-brand-700 dark:text-brand-300" aria-hidden="true">
              📈
            </div>
            <div>
              <div className="font-display font-black text-ink-800 dark:text-cream-100 text-sm">
                روند بازدید ۷ روز اخیر
              </div>
              <div className="text-[11px] text-ink-500 dark:text-cream-400 mt-0.5 font-bold">
                کاربران و مهمان‌ها
              </div>
            </div>
          </div>
          <div className="p-3 sm:p-5">
            <VisitorChart data={stats.daily_series} />
          </div>
        </div>

        {/* تفکیک دستگاه */}
        <div className="bg-paper-50 dark:bg-ink-800 border border-ink-200 dark:border-dark-700 rounded-3xl shadow-soft overflow-hidden">
          <div className="px-4 sm:px-5 py-3 sm:py-4 border-b border-ink-200 dark:border-dark-700 flex items-center gap-3 bg-paper-100/50 dark:bg-ink-900/30">
            <div className="w-9 h-9 rounded-2xl bg-accent-100 dark:bg-accent-500/20 flex items-center justify-center text-lg flex-shrink-0 text-accent-700 dark:text-accent-300" aria-hidden="true">
              📱
            </div>
            <div>
              <div className="font-display font-black text-ink-800 dark:text-cream-100 text-sm">
                دستگاه‌ها (امروز)
              </div>
              <div className="text-[11px] text-ink-500 dark:text-cream-400 mt-0.5 font-bold">
                موبایل / تبلت / دسکتاپ
              </div>
            </div>
          </div>
          <div className="p-4 space-y-3">
            {stats.device_breakdown.length > 0 ? (
              stats.device_breakdown.map((d, i) => {
                const total = stats.today.total || 1;
                const pct = ((d.count / total) * 100).toFixed(0);
                const icon = d.device === 'mobile' ? '📱' : d.device === 'tablet' ? '📲' : '💻';
                const label = d.device === 'mobile' ? 'موبایل' : d.device === 'tablet' ? 'تبلت' : 'دسکتاپ';
                return (
                  <div key={i}>
                    <div className="flex justify-between mb-1.5">
                      <span className="text-xs font-black text-ink-700 dark:text-cream-200 flex items-center gap-1.5">
                        <span>{icon}</span>
                        <span>{label}</span>
                      </span>
                      <span className="text-xs font-black text-ink-800 dark:text-cream-100 font-num tabular-nums">
                        {fmt(d.count)} <span className="text-[10px] text-ink-400">({pct}%)</span>
                      </span>
                    </div>
                    <div className="w-full bg-paper-100 dark:bg-ink-700 rounded-full h-2 overflow-hidden">
                      <div
                        className="h-full bg-brand-gradient rounded-full transition-all duration-700"
                        style={{ width: `${pct}%` }}
                      />
                    </div>
                  </div>
                );
              })
            ) : (
              <div className="text-center text-sm text-ink-400 dark:text-cream-500 py-4">
                <div className="text-3xl mb-1 opacity-50">📭</div>
                <div className="text-xs font-bold">هنوز داده‌ای ثبت نشده</div>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* ===== آخرین بازدیدکنندگان ===== */}
      <div className="bg-paper-50 dark:bg-ink-800 border border-ink-200 dark:border-dark-700 rounded-3xl shadow-soft overflow-hidden">
        <div className="px-4 sm:px-5 py-3 sm:py-4 border-b border-ink-200 dark:border-dark-700 flex items-center gap-3 bg-paper-100/50 dark:bg-ink-900/30">
          <div className="w-9 h-9 rounded-2xl bg-ink-100 dark:bg-ink-700 flex items-center justify-center text-lg flex-shrink-0 text-ink-700 dark:text-cream-200" aria-hidden="true">
            👥
          </div>
          <div>
            <div className="font-display font-black text-ink-800 dark:text-cream-100 text-sm">
              آخرین بازدیدکنندگان
            </div>
            <div className="text-[11px] text-ink-500 dark:text-cream-400 mt-0.5 font-bold">
              ۱۰ بازدید اخیر
            </div>
          </div>
        </div>

        {stats.recent_visitors.length === 0 ? (
          <div className="p-4 text-center text-sm text-ink-400 dark:text-cream-500 py-6">
            <div className="text-3xl mb-1 opacity-50">🕐</div>
            <div className="text-xs font-bold">هنوز بازدیدی ثبت نشده</div>
          </div>
        ) : (
          <div className="overflow-x-auto scrollbar-thin">
            <table className="w-full text-xs">
              <thead className="bg-paper-100 dark:bg-ink-900/50 text-ink-500 dark:text-cream-400">
                <tr>
                  <th className="p-3 text-right font-black text-[11px]">نوع</th>
                  <th className="p-3 text-right font-black text-[11px]">دستگاه</th>
                  <th className="p-3 text-right font-black text-[11px]">صفحه</th>
                  <th className="p-3 text-right font-black text-[11px]">آخرین فعالیت</th>
                  <th className="p-3 text-right font-black text-[11px]">وضعیت</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-ink-200 dark:divide-dark-700">
                {stats.recent_visitors.map((v, i) => (
                  <tr key={i} className="hover:bg-paper-100/60 dark:hover:bg-ink-700/40 transition">
                    <td className="p-3">
                      <span className={`px-2 py-0.5 rounded-full text-[10px] font-black border ${
                        v.user_id
                          ? 'bg-accent-50 dark:bg-accent-500/15 text-accent-700 dark:text-accent-300 border-accent-200 dark:border-accent-500/30'
                          : 'bg-ink-100 dark:bg-ink-700 text-ink-700 dark:text-cream-200 border-ink-200 dark:border-dark-600'
                      }`}>
                        {v.user_id ? '👤 کاربر' : '👻 مهمان'}
                      </span>
                    </td>
                    <td className="p-3 text-ink-700 dark:text-cream-200 font-bold">
                      {v.device === 'mobile' ? '📱 موبایل' : v.device === 'tablet' ? '📲 تبلت' : '💻 دسکتاپ'}
                    </td>
                    <td className="p-3 text-ink-500 dark:text-cream-400 font-num tabular-nums">
                      {fmt(v.page_views)}
                    </td>
                    <td className="p-3 text-ink-500 dark:text-cream-400 font-num tabular-nums">
                      {formatDate(v.last_activity)}
                    </td>
                    <td className="p-3">
                      {v.is_online ? (
                        <span className="inline-flex items-center gap-1 text-[10px] font-black text-accent-600 dark:text-accent-400">
                          <span className="w-1.5 h-1.5 rounded-full bg-accent-500 animate-pulse" aria-hidden="true" />
                          آنلاین
                        </span>
                      ) : (
                        <span className="text-[10px] font-bold text-ink-400 dark:text-cream-500">
                          آفلاین
                        </span>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
}
